package dev.veltraph.client.inventory.bottle;

import dev.veltraph.client.game.GameArea;
import dev.veltraph.client.world.Vec3;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static dev.veltraph.client.inventory.bottle.BottleAcquisitionRuntime.*;
import dev.veltraph.client.inventory.bottle.BottleFillWorkflow.Identity;
import dev.veltraph.client.inventory.bottle.BottleFillWorkflow.Position;
import dev.veltraph.client.inventory.bottle.BottleFillWorkflow.Stack;

class BottleAcquisitionRuntimeTest {
    static final Identity GLASS=new Identity("minecraft:glass_bottle","Glass Bottle","[glass]"),OPTION=new Identity("minecraft:paper","Trading options","[option]"),OFFER=new Identity("minecraft:glass_bottle","64 Glass Bottles","[offer]"),TOOL=new Identity("minecraft:diamond_sword","Protected tool","[tool]");
    static Profile profile(int cycles,long budget){return new Profile(GLASS,new Landing("privatehub",GameArea.HUB,"minecraft:overworld",new Vec3(0.5,70,.5)),new Landing("privateisland",GameArea.ISLAND,"minecraft:overworld",new Vec3(10.5,70,.5)),List.of(new Position(1,70,0),new Position(2,70,0),new Position(3,70,0)),new Position(4,70,0),new Position(3,70,0),"PrivateWitch","minecraft:witch","Private NPC",OPTION,"Private Quotes",OFFER,4,cycles,100,budget,1,30,2000);}
    static final class Fake implements Port {
        Object player=new Object(),world=new Object(),connection=new Object(),menu;UUID uuid=UUID.randomUUID();GameArea area=GameArea.ISLAND;Vec3 pos=new Vec3(10.5,70,.5),teleport;String title="";long serial,now;int revision,selected=2,readCalls,commands,walks,interactions,options,purchases,closes,fills,returnCalls;boolean predicted=true,deliver=true,withholdTravel,withholdFill,returnReceipt=true,cursorEmpty=true;long price=10;int purchaseQuantity=64,fillCount=64;Stack predictedCursor=Stack.EMPTY;int currentFill=-1;List<Stack> inventory=new ArrayList<>(Collections.nCopies(36,Stack.EMPTY));
        Fake(){inventory.set(2,new Stack(TOOL,1,true));}
        public Observation read(){readCalls++;List<Slot> rows=title.equals("Private NPC")?List.of(new Slot(4,false,new Stack(OPTION,1,false),List.of())):title.equals("Private Quotes")?List.of(new Slot(7,false,new Stack(OFFER,64,false),List.of("Amount: 64x","Price: "+price+" Coins"))):List.of();return new Observation(player,world,connection,uuid,"minecraft:overworld",area,pos,10,5,true,true,menu,title,menu==null?0:1,revision,cursorEmpty?predictedCursor:new Stack(TOOL,1,true),selected,inventory,rows,serial,teleport,now);}
        public boolean command(Observation o,Landing landing){commands++;if(!withholdTravel){world=new Object();area=landing.area();pos=teleport=landing.position();serial++;}return true;}
        public Progress walk(Observation o,Position p){walks++;pos=new Vec3(p.x()+.5,p.y(),p.z()+.5);return Progress.COMPLETE;}
        void open(String text){menu=new Object();title=text;revision=1;}
        public Progress npc(Observation o,Profile p,boolean issue){interactions++;open(p.npcTitle());return Progress.COMPLETE;}
        public boolean click(Observation o,Slot s){if(s.stack().identity().equals(OPTION)){options++;open("Private Quotes");}else{purchases++;if(predicted&&deliver){for(int i=0;i<36;i++)if(inventory.get(i).empty()){inventory.set(i,new Stack(GLASS,purchaseQuantity,false));break;}}}return true;}
        public boolean close(Observation o){closes++;menu=null;title="";return true;}
        public void release(){}public boolean beginFill(int index,long tick){currentFill=index;fills++;return true;}
        public Progress fill(long tick){if(withholdFill)return Progress.WAITING;inventory.set(currentFill,Stack.EMPTY);return Progress.COMPLETE;}public int filled(){return fillCount;}
        public boolean returnPose(Observation o,Vec3 p,float yaw,float pitch){returnCalls++;if(returnReceipt)pos=p;return returnReceipt;}public void cancelFill(){}
    }
    static final class Run {final Fake port=new Fake();final BottleAcquisitionRuntime runtime=new BottleAcquisitionRuntime(port);long tick;Run(){assertTrue(runtime.start(profile(1,1000),0));}void next(){port.now=++tick*50;runtime.tick(tick);}void reach(State state){for(int i=0;i<5000&&runtime.state()!=state&&runtime.active();i++)next();assertEquals(state,runtime.state(),runtime.reason());}void finish(){for(int i=0;i<10000&&runtime.active();i++)next();}}
    @Test void fullSourceRoutePurchasesEveryIndependent64ThenIslandRefillReturn(){var r=new Run();r.finish();assertEquals(State.COMPLETE,r.runtime.state(),r.runtime.reason());assertEquals(5,r.port.purchases);assertEquals(6,r.port.interactions);assertEquals(6,r.port.options);assertEquals(2,r.port.commands);assertEquals(3,r.port.walks);assertEquals(5,r.port.fills);assertEquals(320,r.runtime.filled());assertEquals(5,r.runtime.receipts().size());assertEquals(50,r.runtime.spent());assertTrue(r.port.inventory.get(2).tool());assertEquals(new Vec3(10.5,70,.5),r.port.pos);assertEquals(1,r.port.returnCalls);}
    @Test void predictionAloneNeverCreditsAPurchaseOrStartsNextRequest(){var r=new Run();r.reach(State.WAIT_BUY);assertEquals(64,r.port.inventory.stream().filter(GLASS::matches).mapToInt(Stack::count).sum());assertEquals(0,r.runtime.acquired());assertEquals(0,r.runtime.receipts().size());assertEquals(1,r.port.purchases);}
    @Test void missingPurchaseIndependentReceiptUnknownAndNoRetry(){var r=new Run();r.port.deliver=false;r.finish();assertEquals(State.UNKNOWN,r.runtime.state());assertEquals(1,r.port.purchases);assertEquals(0,r.runtime.acquired());assertEquals(0,r.port.fills);}
    @Test void partial63ReceiptCannotCredit64(){var r=new Run();r.port.purchaseQuantity=63;r.finish();assertEquals(State.UNKNOWN,r.runtime.state());assertEquals(1,r.port.purchases);assertEquals(0,r.runtime.spent());}
    @Test void unrelatedProtectedDeltaRejectsFreshReceipt(){var r=new Run();r.reach(State.WAIT_BUY);r.port.inventory.set(2,Stack.EMPTY);r.finish();assertEquals(State.UNKNOWN,r.runtime.state());assertEquals(1,r.port.purchases);assertEquals(0,r.runtime.receipts().size());}
    @Test void sameTitleForeignPurchaseMenuPreserved(){var r=new Run();r.reach(State.WAIT_BUY);r.port.open("Private Quotes");Object foreign=r.port.menu;r.next();assertEquals(State.UNKNOWN,r.runtime.state());assertSame(foreign,r.port.menu);assertEquals(0,r.port.closes);}
    @Test void oldRetiredPurchaseMenuCannotAcknowledgePrediction(){var r=new Run();r.reach(State.WAIT_BUY);Object old=r.port.menu;r.reach(State.VERIFY_BUY);r.port.menu=old;r.next();assertEquals(State.UNKNOWN,r.runtime.state());assertEquals(0,r.runtime.acquired());}
    @Test void lateOtherwisePerfectReceiptRejectedBeforeAdoption(){var r=new Run();r.reach(State.VERIFY_BUY);r.tick+=31;r.next();assertEquals(State.UNKNOWN,r.runtime.state());assertEquals(0,r.runtime.receipts().size());}
    @Test void exactDeadlineReceiptStillAccepted(){var r=new Run();r.reach(State.VERIFY_BUY);r.tick+=29;r.next();assertEquals(1,r.runtime.acquired());}
    @Test void cancellationAfterIssuedPurchaseIsDurableUnknownAndNoLateAdvancement(){var r=new Run();r.reach(State.WAIT_BUY);r.runtime.cancel();assertEquals(State.UNKNOWN,r.runtime.state());r.finish();assertEquals(1,r.port.purchases);assertEquals(0,r.port.fills);assertThrows(IllegalStateException.class,()->r.runtime.start(profile(1,1000),500));}
    @Test void cancellationBeforeRequestSendsNoWork(){var r=new Run();r.runtime.cancel();r.finish();assertEquals(State.CANCELLED,r.runtime.state());assertEquals(0,r.port.commands);}
    @Test void changedConnectionNeverAdoptedEvenAtExpectedLanding(){var r=new Run();r.reach(State.WAIT_TRAVEL);r.port.connection=new Object();r.next();assertEquals(State.FAILED,r.runtime.state());assertEquals(0,r.port.interactions);}
    @Test void missingTeleportReceiptDoesNotUseMatchingPose(){var r=new Run();r.port.withholdTravel=true;r.reach(State.WAIT_TRAVEL);r.port.pos=profile(1,1000).hub().position();r.port.area=GameArea.HUB;r.finish();assertEquals(State.FAILED,r.runtime.state());assertEquals(1,r.port.commands);assertEquals(0,r.port.interactions);}
    @Test void incorrectNativeLandingRejected(){var r=new Run();r.reach(State.WAIT_TRAVEL);r.port.teleport=new Vec3(30,70,0);r.next();assertEquals(State.FAILED,r.runtime.state());}
    @Test void exactQuoteCumulativeBudgetCheckedBeforeEachPurchase(){var r=new Run();r.reach(State.BUY);r.port.price=100;r.runtime.cancel();var p=new Fake();p.price=100;var rt=new BottleAcquisitionRuntime(p);assertTrue(rt.start(profile(1,150),0));for(int i=1;i<1000&&rt.active();i++){p.now=i*50;rt.tick(i);}assertEquals(State.FAILED,rt.state());assertEquals(1,p.purchases);assertEquals(100,rt.spent());assertEquals(0,p.fills);}
    @Test void changedQuoteCannotExceedPerStackCap(){var r=new Run();r.reach(State.BUY);r.port.price=101;r.next();assertEquals(State.FAILED,r.runtime.state());assertEquals(0,r.port.purchases);}
    @Test void ownPredictedOfferCursorWaitsWithoutCreditingOrClosing(){var r=new Run();r.reach(State.WAIT_BUY);r.port.predictedCursor=new Stack(OFFER,64,false);r.next();assertEquals(State.WAIT_BUY,r.runtime.state());assertEquals(0,r.runtime.acquired());assertEquals(0,r.port.closes);r.port.predictedCursor=Stack.EMPTY;r.next();assertEquals(State.VERIFY_NPC,r.runtime.state());}
    @Test void foreignCursorPreservedWithoutFollowupAction(){var r=new Run();r.reach(State.WAIT_BUY);r.port.cursorEmpty=false;r.next();assertEquals(State.UNKNOWN,r.runtime.state());assertFalse(r.port.cursorEmpty);assertEquals(0,r.port.closes);}
    @Test void missingRefillReceiptNeverReturnsOrStartsAnotherCycle(){var r=new Run();r.port.withholdFill=true;r.finish();assertEquals(State.UNKNOWN,r.runtime.state());assertEquals(5,r.port.purchases);assertEquals(1,r.port.fills);assertEquals(0,r.port.returnCalls);}
    @Test void partialRefillReceiptRejectsAll64Claim(){var r=new Run();r.port.fillCount=63;r.finish();assertEquals(State.UNKNOWN,r.runtime.state());assertEquals(0,r.runtime.filled());assertEquals(1,r.port.fills);}
    @Test void finiteTwoCyclesRequireTenIndependentPurchases(){var p=new Fake();var rt=new BottleAcquisitionRuntime(p);assertTrue(rt.start(profile(2,1000),0));for(int i=1;i<10000&&rt.active();i++){p.now=i*50;rt.tick(i);}assertEquals(State.COMPLETE,rt.state(),rt.reason());assertEquals(10,p.purchases);assertEquals(10,rt.receipts().size());assertEquals(640,rt.filled());assertEquals(4,p.commands);assertEquals(6,p.walks);}
    @Test void observedReturnReceiptRequired(){var r=new Run();r.port.returnReceipt=false;r.finish();assertEquals(State.FAILED,r.runtime.state());assertEquals(320,r.runtime.filled());assertTrue(r.port.returnCalls>0);}
    @Test void changedAreaOutsideIssuedTravelStopsBeforeAnyPurchase(){var r=new Run();r.reach(State.BUY);r.port.area=GameArea.THE_END;r.next();assertEquals(State.FAILED,r.runtime.state());assertEquals(0,r.port.purchases);}
    @Test void unknownReceiptNeedsExactExplicitManualLedgerRecovery(){var r=new Run();r.port.deliver=false;r.finish();assertEquals(State.UNKNOWN,r.runtime.state());r.port.open("Private Quotes");assertFalse(r.runtime.acknowledgeManualRecovery());r.port.menu=null;r.port.title="";assertTrue(r.runtime.acknowledgeManualRecovery());assertEquals(State.FAILED,r.runtime.state());assertEquals(0,r.runtime.receipts().size());}
    @Test void thresholdStrictlyGreaterThanFourToSix(){assertEquals(5,profile(1,1000).stacks());assertThrows(IllegalArgumentException.class,()->new Profile(GLASS,profile(1,1000).hub(),profile(1,1000).island(),profile(1,1000).path(),new Position(4,70,0),new Position(3,70,0),"PrivateWitch","minecraft:witch","NPC",OPTION,"Buy",OFFER,3,1,100,1000,1,30,2000));}
}
